Method.Source:
/// <summary>
/// Insert hanlder
/// </summary>
/// <param name="sender">cust table record</param>
/// <param name="e">data event</param>
[DataEventHandler(tableStr(CustTable), DataEventType::Inserted)]
public static void CustTable_onInserted(Common sender, DataEventArgs e)
{
    CustTable custTable = sender as CustTable;
    METPriceChangeEventCustomer::metProcessTrackChange(custTable);
}
